from __future__ import absolute_import

import time
from selenium.webdriver.common.by import By
from taf.selenium.sbts.common.common import LocalBasicPage


class ViewPanel(LocalBasicPage):
    _DETAIL_PANEL_XPATH = ("//details-panel[@documentation='details']"
                           "//wf-panel[@panel-name='admin.common.detailsPanel.TITLE']")
    _SCROLL_INTO_VIEW_JS = 'arguments[0].scrollIntoView({behavior: "smooth", block: "center", inline: "center"});'

    def __init__(self, driver, download_checker=None, screenshot_dir=None):
        super(ViewPanel, self).__init__(driver, download_checker, screenshot_dir)

    def show_detail_panel(self, xpath, index=0):
        self.wait_for_visibility((By.XPATH, xpath))
        self.driver.execute_script(self._SCROLL_INTO_VIEW_JS, self.driver.find_element_by_xpath(xpath))
        time.sleep(2)
        self.wait_for_visibility((By.XPATH, xpath))
        self.driver.execute_script('arguments[0].click();', self.driver.find_elements_by_xpath(xpath)[index])
        self.wait_for_visibility((By.XPATH, self._DETAIL_PANEL_XPATH))
